/* ── La llave de la liga se DERIVA, no se agrega al entorno ────────────────
 * Decision propia de la sesion del 27/28-sep-2026: agregar una variable nueva
 * a Railway estaba fuera de lo autorizado, y ademas una llave por proposito es
 * mejor practica que reusar la de las sesiones. Las dos cosas se resuelven
 * derivandola:
 *
 *     k = HMAC(SUITE_JWT_SECRET, 'fts-comision-aprobar-v1')
 *
 * Es separacion de llaves estandar: de `k` no se saca el secreto de las
 * sesiones, asi que una liga filtrada no compromete el login de nadie, y al
 * contrario tampoco. La etiqueta lleva version por si algun dia hay que
 * invalidar todas las ligas vivas de golpe: se sube a -v2 y se caen solas. */
function llaveLiga(secreto) {
  return hex(hmacSha256('' + secreto, 'fts-comision-aprobar-v1'));
}
/* El token son tres partes: la solicitud, un azar de 24 bytes que sale de
 * `gen_random_bytes` de Postgres (CSPRNG de verdad — el sandbox de n8n no
 * expone uno, y `Math.random` no sirve para esto), y la firma de las dos.
 *
 * La firma es lo que hace que no se pueda inventar una liga: sin `k` no se
 * puede producir un `sig` valido para ninguna solicitud, ni conociendo su id. */
function armarToken(k, sol, nonce) {
  return sol + '.' + nonce + '.' + b64urlFromBytes(hmacSha256(k, sol + '.' + nonce));
}
/* Verifica la FORMA y la FIRMA. No toca la base: eso es el segundo candado y
 * va aparte a proposito — asi una liga inventada se rechaza sin gastar una
 * consulta, y una liga bien firmada pero ya usada da un mensaje distinto. */
function abrirToken(k, token) {
  const t = '' + (token || '');
  if (!t || t.length > 300) return { ok:false, error:'LIGA_MALFORMADA' };
  const p = t.split('.');
  if (p.length !== 3) return { ok:false, error:'LIGA_MALFORMADA' };
  const sol = p[0], nonce = p[1], sig = p[2];
  if (!/^[0-9a-f-]{36}$/.test(sol))  return { ok:false, error:'LIGA_MALFORMADA' };
  if (!/^[0-9a-f]{48}$/.test(nonce)) return { ok:false, error:'LIGA_MALFORMADA' };
  const esperada = b64urlFromBytes(hmacSha256(k, sol + '.' + nonce));
  if (!safeEq(sig, esperada)) return { ok:false, error:'FIRMA_INVALIDA' };
  return { ok:true, sol: sol, nonce: nonce, huella: sha256Hex(t) };
}

/* ── comercial/comision-pedir · verificar la sesion y preparar la solicitud ──
 * TODO en try/catch: la entrada es el Set que resolvio $env.SUITE_JWT_SECRET, y
 * un nodo que truena devuelve su ENTRADA en nodeExecutionStack — el 8-sep-2026
 * asi acabo una llave de produccion en un transcript (CLAUDE.md §9). */
try {
  const ENTRADA = $input.first().json;
  const cuerpo  = ENTRADA.body || ENTRADA || {};
  const secreto = $('Set - secreto').item.json.secret;
  if (!secreto || ('' + secreto).length < 32) {
    return [{ json: { ok:false, error:'SECRETO_NO_CONFIGURADO',
      mensaje:'SUITE_JWT_SECRET no esta definida o es muy corta en el entorno de n8n.' } }];
  }
  const v = verifyJWT(cuerpo.token, '' + secreto, 'comercial:read');
  if (!v.ok) {
    return [{ json: { ok:false, error:v.error,
      mensaje: v.error === 'TOKEN_EXPIRADO' ? 'La sesion vencio. Vuelve a entrar.'
             : v.error === 'SCOPE_INSUFICIENTE' ? 'Tu usuario no tiene acceso al modulo comercial.'
             : 'Sesion no valida. Vuelve a entrar.' } }];
  }
  if (v.scopes.indexOf('comercial:write') < 0) {
    return [{ json: { ok:false, error:'SIN_PERMISO_ESCRITURA',
      mensaje:'Tu usuario puede leer el modulo comercial pero no pedir autorizaciones.' } }];
  }
  const ben = ('' + (cuerpo.beneficiario_id || '')).trim();
  if (!/^[0-9a-f-]{36}$/.test(ben)) {
    return [{ json: { ok:false, error:'SIN_BENEFICIARIO',
      mensaje:'Falta el beneficiario, o su id no tiene forma de id.' } }];
  }

  /* ── La caducidad ───────────────────────────────────────────────────────
   * 72 horas. Decision propia, y el razonamiento importa mas que el numero:
   * una liga que aprueba algo no puede vivir para siempre en una bandeja, y al
   * mismo tiempo tiene que aguantar un fin de semana — si vence en 24 h, todo
   * lo que se pida un viernes nace muerto. 72 h cubre viernes→lunes.
   * Se puede pedir otra cosa entre 1 y 168 h; fuera de ese rango se ignora y
   * se DICE, en vez de aceptar un 0 que caduca al instante. */
  let horas = Number(cuerpo.horas);
  const horas_pedidas = cuerpo.horas === undefined ? null : Number(cuerpo.horas);
  if (!(horas >= 1 && horas <= 168)) horas = 72;

  return [{ json: { ok:true, actor:v.actor, nombre_actor:v.nombre,
    beneficiario_id: ben, horas: horas,
    horas_ignoradas: horas_pedidas !== null && horas_pedidas !== horas,
    reenvio: cuerpo.reenvio === true } }];
} catch (e) {
  return [{ json: { ok:false, error:'FALLO_VERIFICACION', mensaje:'No se pudo validar la sesion.' } }];
}

/* ── Que hacer con lo que hay ──────────────────────────────────────────────
 * Cuatro respuestas posibles, y ninguna es «error»:
 *   - el beneficiario no existe                 -> no se puede pedir
 *   - ya esta vigente                           -> no hace falta pedir nada
 *   - hay una solicitud viva y NO es reenvio    -> se dice que ya se pidio, y cuando
 *   - hay una viva y SI es reenvio              -> se anula la anterior y se manda otra
 * El indice `comision_apr_viva_uq` de la migracion 010 solo deja UNA viva por
 * beneficiario, asi que el reenvio TIENE que anular; si no, el INSERT choca.
 * Que el candado este en la base y no solo aqui es a proposito: asi no depende
 * de que este nodo se haya acordado. */
const filas = $input.all().map(i => i.json).filter(f => f && f.id);
const pet = $('Code - Verificar').first().json;

if (!filas.length) {
  return [{ json: { ok:false, error:'BENEFICIARIO_NO_EXISTE',
    mensaje:'Ese beneficiario no esta en el catalogo. Puede que se haya archivado.' } }];
}
const b = filas[0];
if (b.estado === 'vigente') {
  return [{ json: { ok:true, hecho:false, ya:'vigente', beneficiario_id:b.id, nombre:b.nombre,
    mensaje: b.nombre + ' ya esta autorizado. No hace falta pedir nada.' } }];
}
if (b.estado === 'archivado' || b.estado === 'rechazado') {
  return [{ json: { ok:false, error:'BENEFICIARIO_' + String(b.estado).toUpperCase(),
    mensaje: b.nombre + ' esta ' + b.estado + '. Para volver a usarlo hay que darlo de alta otra vez.' } }];
}
if (b.solicitud_viva && !pet.reenvio) {
  return [{ json: { ok:true, hecho:false, ya:'pedida', beneficiario_id:b.id, nombre:b.nombre,
    solicitud_id:b.solicitud_viva, pedido_at:b.pedido_at, vence_at:b.vence_at,
    pedido_a:b.pedido_a, recordatorios:b.recordatorios,
    mensaje: 'Ya se pidio la autorizacion de ' + b.nombre + '. Vence el ' +
             String(b.vence_at || '').slice(0,16).replace('T',' ') + ' UTC.' } }];
}
/* Sigue: hay que crear la solicitud (y anular la anterior si era reenvio). */
return [{ json: { ok:true, hecho:null, crear:true,
  beneficiario_id: b.id, nombre: b.nombre, tipo: b.tipo, motivo: b.motivo,
  odoo_cuenta_id: b.odoo_cuenta_id, anular: b.solicitud_viva || null,
  horas: pet.horas, horas_ignoradas: pet.horas_ignoradas, actor: pet.actor } }];

