/* Verifica la FORMA y la FIRMA. No toca la base: eso es el segundo candado y
 * va aparte a proposito — asi una liga inventada se rechaza sin gastar una
 * consulta, y una liga bien firmada pero ya usada da un mensaje distinto. */
function abrirToken(k, token) {
  const t = '' + (token || '');
  if (!t || t.length > 300) return { ok:false, error:'LIGA_MALFORMADA' };
  const p = t.split('.');
  if (p.length !== 3) return { ok:false, error:'LIGA_MALFORMADA' };
  const sol = p[0], nonce = p[1], sig = p[2];
  if (!/^[0-9a-f-]{36}$/.test(sol))  return { ok:false, error:'LIGA_MALFORMADA' };
  if (!/^[0-9a-f]{48}$/.test(nonce)) return { ok:false, error:'LIGA_MALFORMADA' };
  const esperada = b64urlFromBytes(hmacSha256(k, sol + '.' + nonce));
  if (!safeEq(sig, esperada)) return { ok:false, error:'FIRMA_INVALIDA' };
  return { ok:true, sol: sol, nonce: nonce, huella: sha256Hex(t) };
}

/* ── Firmar la liga ────────────────────────────────────────────────────────
 * try/catch total por lo mismo de siempre: la entrada trae el secreto.
 *
 * Y el orden importa: la liga se firma ANTES de guardar, y lo que se guarda es
 * su huella. Asi la base nunca ve el token — si se filtra, lo que se filtra no
 * abre nada (de un sha256 no se saca el original). Es la misma razon por la que
 * una contrasena se guarda hasheada. */
try {
  const s = $input.first().json;
  const secreto = $('Set - secreto 2').item.json.secret;
  if (!secreto || ('' + secreto).length < 32) {
    return [{ json: { ok:false, error:'SECRETO_NO_CONFIGURADO',
      mensaje:'SUITE_JWT_SECRET no esta definida en el entorno de n8n.' } }];
  }
  const d = $('Code - Decidir').first().json;
  const k = llaveLiga(secreto);
  const token = armarToken(k, s.sol, s.nonce);
  const vence = new Date(Date.now() + d.horas * 3600 * 1000);
  return [{ json: { ok:true,
    sol: s.sol, huella: sha256Hex(token), token: token,
    anuladas: s.anuladas,
    beneficiario_id: d.beneficiario_id, nombre: d.nombre, tipo: d.tipo,
    motivo: d.motivo, odoo_cuenta_id: d.odoo_cuenta_id,
    horas: d.horas, horas_ignoradas: d.horas_ignoradas, actor: d.actor,
    vence_iso: vence.toISOString(),
    liga: 'https://primary-production-5c3c.up.railway.app/webhook/comercial/comision-liga?t=' + encodeURIComponent(token) } }];
} catch (e) {
  return [{ json: { ok:false, error:'FALLO_FIRMA', mensaje:'No se pudo firmar la liga.' } }];
}
